/**
 * inactive has no purchase; pending is a first purchase whose order has not been accepted;
 * provisioning is a first purchase being activated; active permits creation within available
 * capacity; suspended refuses new creation; failed means the first purchase failed, as
 * failure_reason states. A pending change keeps the current status and limit until it is applied.
 */
export type SnapshotQuotaStatus = (typeof SnapshotQuotaStatus)[keyof typeof SnapshotQuotaStatus];

export const SnapshotQuotaStatus = {
  inactive: "inactive",
  pending: "pending",
  provisioning: "provisioning",
  active: "active",
  suspended: "suspended",
  failed: "failed",
} as const;

/**
 * Why the first purchase failed; null unless status is failed. A failed change leaves the current
 * limit in force and clears pending_limit; its order shows the outcome.
 * @nullable
 */
export type SnapshotQuotaFailureReason =
  | (typeof SnapshotQuotaFailureReason)[keyof typeof SnapshotQuotaFailureReason]
  | null;

export const SnapshotQuotaFailureReason = {
  order_declined: "order_declined",
  order_canceled: "order_canceled",
  order_expired: "order_expired",
  provisioning_failed: "provisioning_failed",
} as const;

/**
 * Snapshot count capacity for the authenticated project and one region, projected from its
 * effective quota purchase and Compute's actual holdings. This is not a Billing Allowance:
 * creation occupies capacity and confirmed deletion releases it rather than consuming a grant.
 * Pending purchases never increase effective capacity before commercial acceptance and activation.
 */
export interface SnapshotQuota {
  region_id: string;
  /**
   * inactive has no purchase; pending is a first purchase whose order has not been accepted;
   * provisioning is a first purchase being activated; active permits creation within available
   * capacity; suspended refuses new creation; failed means the first purchase failed, as
   * failure_reason states. A pending change keeps the current status and limit until it is applied.
   */
  status: SnapshotQuotaStatus;
  /**
   * Effective maximum concurrent snapshot count. Zero until the first purchase is activated.
   * @minimum 0
   */
  limit: number;
  /**
   * Held and reserved snapshot slots, including pending creation and unconfirmed cleanup.
   * @minimum 0
   */
  used: number;
  /**
   * max(limit - used, 0), or zero while creation is not permitted.
   * @minimum 0
   */
  available: number;
  /**
   * The order establishing the currently associated quota purchase, including an initial pending purchase.
   * @nullable
   */
  order_id: string | null;
  /**
   * The quota purchase's Billing subscription, not an individual snapshot subscription.
   * May still be pending on an initial purchase; an existing subscription remains associated
   * until a replacement quota is activated. Null when no purchase has been recorded.
   * @nullable
   */
  subscription_id: string | null;
  /** The billing choice of the associated quota purchase, as given when it was bought. A change of an existing purchase has to give the same choice. Null when no purchase has been recorded. */
  billing: BillingChoice | null;
  /** The subscription a cancellation through Billing has to cover to release this snapshot quota. A subscription that has ended is not listed, and the list is empty when no subscription pays for the quota. */
  release_subscription_ids: string[];
  /**
   * Target count awaiting checkout or activation; null when no purchase is pending.
   * @minimum 1
   * @nullable
   */
  pending_limit: number | null;
  /**
   * Order for the pending initial purchase or change; null when none is pending.
   * @nullable
   */
  pending_order_id: string | null;
  /**
   * Why the first purchase failed; null unless status is failed. A failed change leaves the current
   * limit in force and clears pending_limit; its order shows the outcome.
   * @nullable
   */
  failure_reason: SnapshotQuotaFailureReason;
  /** How snapshot quota in this region can be bought, per snapshot slot. Null when the project has no billing account. */
  readonly pricing: Pricing | null;
}

export interface SetSnapshotQuotaRequestBody {
  /**
   * Desired total concurrent snapshot count for this project and region, not additional slots.
   * @minimum 1
   */
  limit: number;
  billing: BillingChoice;
  checkout?: CheckoutOptions;
  /** The `proration_date` of this change's quote, so that the order is priced from the same instant. Defaults to the time of the request; it must be a whole second, not in the future and at most 10 minutes old, otherwise the request is refused with `BILLING_CHANGE_INVALID`. */
  proration_date?: string;
}

/**
 * A draft is not yet issued. The draft invoice of an order shows base prices until it is paid, when
 * the discount is applied and it is issued; other drafts are private to administrators.
 * An issued invoice is open until settled; a zero-total issued invoice is immediately paid.
 * Unbilled usage remains separate from invoices until it is invoiced.
 * A refund does not change the status: a paid invoice stays paid, with the refunded part in
 * amount_refunded. void means collection has stopped and any funds received have been returned.
 */
export type InvoiceStatus = (typeof InvoiceStatus)[keyof typeof InvoiceStatus];

export const InvoiceStatus = {
  draft: "draft",
  open: "open",
  paid: "paid",
  void: "void",
  uncollectible: "uncollectible",
} as const;

/**
 * Purchase-related invoice amounts, without account contact details or payment methods. Every order
 * has an invoice from placement. A draft shows base prices until it is paid, when the discount is
 * applied and it is issued; a zero-total invoice is issued and paid at placement whatever the
 * checkout mode. Neither establishes acceptance or delivery.
 */
export interface InvoiceSummary {
  id: string;
  number?: string;
  currency: string;
  status: InvoiceStatus;
  /**
   * Sum of the line amounts before discounts. Where prices include tax, the tax contained in
   * each line's discounted amount is taken out here, so that total = subtotal -
   * discount_amount + tax_amount always holds.
   */
  subtotal: string;
  /** Sum of the line discounts, taken off before tax. */
  discount_amount: string;
  tax_amount: string;
  total: string;
  amount_paid: string;
  /** Issued, non-void credit notes that reduced unpaid receivables. Does not rewrite the original invoice total. */
  pre_payment_credit_notes_amount: Money;
  /** Issued credit notes against payments already received. This is a return obligation, not evidence of completed refunds. */
  post_payment_credit_notes_amount: Money;
  /**
   * What is still collectible after unpaid credit notes and successful payments; never below zero.
   * @pattern ^\d+(\.\d{1,10})?$
   */
  amount_due: string;
  amount_refunded: string;
  due_at?: string;
}

/**
 * The Billing order this purchase placed and its invoice as they stood at placement. Read the order and
 * the invoice in Billing for current progress: the service starts delivery only after Billing accepts the
 * order, and payment alone does not mean delivery has completed.
 */
export interface PlacedOrder {
  order_id: string;
  /** The order's invoice, the same as invoice.id. */
  invoice_id: string;
  /**
   * What the purchase charges. A draft shows the base price in total and is paid through Billing, where a
   * promotion code can still be applied; an open invoice is issued and awaits its amount_due; a paid one
   * needs nothing further. A zero-total invoice is issued and paid at placement.
   */
  invoice: InvoiceSummary;
}

